3.6. Inheritance: CREATE TABLE capitals (
  name       text,
  population real,
  elevation  int,    -- (in ft)
  state      char(2)
);

CREATE TABLE non_capitals (
  name       text,
  population real,
  elevation  int     -- (in ft)
);

CREATE VIEW cities AS
  SELECT name, population, elevation FROM capitals
    UNION
  SELECT name, population, elevation FROM non_capitals;

3.6. Inheritance: CREATE TABLE cities (
  name       text,
  population real,
  elevation  int     -- (in ft)
);

CREATE TABLE capitals (
  state      char(2) UNIQUE NOT NULL
) INHERITS (cities);

3.6. Inheritance: SELECT name, elevation
  FROM cities
  WHERE elevation > 500;

3.6. Inheritance: SELECT name, elevation
    FROM ONLY cities
    WHERE elevation > 500;
